import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Why is my SSD Pool so Slow? Decoupling min_size from Write Acknowledgment","description":"","frontmatter":{"title":"Why is my SSD Pool so Slow? Decoupling min_size from Write Acknowledgment","date":"2026-04-20T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["Ceph","OSD","performance tuning","high availability","distributed storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Why_is_my_SSD_Pool_so_Slow_Decoupling_min_size_from_Write_Acknowledgment.md","filePath":"posts/2026/Why_is_my_SSD_Pool_so_Slow_Decoupling_min_size_from_Write_Acknowledgment.md","lastUpdated":1780459816000}'),n={name:"posts/2026/Why_is_my_SSD_Pool_so_Slow_Decoupling_min_size_from_Write_Acknowledgment.md"};function r(l,e,d,c,s,_){return i(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="演讲者背景" tabindex="-1">演讲者背景 <a class="header-anchor" href="#演讲者背景" aria-label="Permalink to &quot;演讲者背景&quot;">​</a></h2><p>演讲者是一位来自圣安东尼奥的独立顾问，27岁，从事相关工作近十年。此前在当地一家大型托管服务提供商担任运维职位，主要工作方向之一是帮助企业从公有云迁移回自建基础设施，背景是近年来云计算成本持续攀升。他从2017年前后开始在家庭实验室中使用 Ceph，起因是 Proxmox 宣布集成 Ceph。目前主要支持 Windows VDI 场景，这也是他深入研究 Ceph performance tuning 的直接动力。</p><h2 id="问题背景-sd-价格上涨与-tco-压力" tabindex="-1">问题背景：SD 价格上涨与 TCO 压力 <a class="header-anchor" href="#问题背景-sd-价格上涨与-tco-压力" aria-label="Permalink to &quot;问题背景：SD 价格上涨与 TCO 压力&quot;">​</a></h2><p>过去18个月，企业级 SSD 价格涨幅超过两倍，部分企业级 NVMe SSD 甚至接近三倍涨幅。相比之下，HDD 价格并未出现同等幅度的上涨。这一现实导致在预算会议中，即便应用对 NVMe 级别的低延迟有强烈需求，财务部门也往无法批准全 SD 方案。</p><p>这促使演讲者思考：<strong>能否通过混合 CRUSH rule 降低 TCO，同时保持可接受的性能？</strong></p><h2 id="混合池方案构想" tabindex="-1">混合池方案构想 <a class="header-anchor" href="#混合池方案构想" aria-label="Permalink to &quot;混合池方案构想&quot;">​</a></h2><p>演讲者提出了一种 hybrid pool 方案：</p><ul><li>将数据的两份副本存放在 SD OSD 上</li><li>将第三份副本存放在 HDD（spinning disk）OSD 上</li><li>pool 配置为 <code>size=3, min_size=2</code></li></ul><p>理论上，这样可以将存储成本降低约三分之一，同时在正常读写路径上利用 SSD 的低延迟。</p><h2 id="核心问题-write-acknowledgment-机制" tabindex="-1">核心问题：Write Acknowledgment 机制 <a class="header-anchor" href="#核心问题-write-acknowledgment-机制" aria-label="Permalink to &quot;核心问题：Write Acknowledgment 机制&quot;">​</a></h2><p>演讲者深入分析了为何这一方案在 Squid 版本中性能急剧下降。</p><h3 id="关键代码路径-submit-transaction" tabindex="-1">关键代码路径：<code>submit_transaction</code> <a class="header-anchor" href="#关键代码路径-submit-transaction" aria-label="Permalink to &quot;关键代码路径：`submit_transaction`&quot;">​</a></h3><p>通过阅读 Ceph 源码（而非文档），可以发现：</p><ul><li>客户端收到最终写确认（write acknowledgment）的条件是：<strong><code>waiting_for_commit</code> 集合完全清空</strong></li><li>该集合并不参考 pool 的<code>min_size</code> 配置，而是直接基于 <strong>acting set</strong> 中的所有 OSD</li><li>如果 acting set 中存在正在 backfill 的 PG，这些 backfill 目标 OSD 同样会被纳入等待集合</li></ul><p>这意味着，即便 <code>min_size=2</code>，只要 acting set 中有一个 HDD OSD 正在参与，写延迟就会被拉低到 HDD 的水平。</p><h3 id="squid-版本的重大变化" tabindex="-1">Squid 版本的重大变化 <a class="header-anchor" href="#squid-版本的重大变化" aria-label="Permalink to &quot;Squid 版本的重大变化&quot;">​</a></h3><p>在 Squid 之前（Quincy、Reef 等版本），系统存在 <code>waiting_for_apply</code> 机制，允许利用 replica 侧的 page cache 提前返回确认，变相规避了等待 HDD 物理寻道的延迟。</p><p><strong>Squid 版本彻底移除了 <code>waiting_for_apply</code></strong>，replica 侧缓存不再接受未打标签的回复，page cache 的&quot;作弊&quot;路径被关闭。这使得混合池方案在 Squid 下几乎不可用。</p><h3 id="全ssd-池同样受影响" tabindex="-1">全SSD 池同样受影响 <a class="header-anchor" href="#全ssd-池同样受影响" aria-label="Permalink to &quot;全SSD 池同样受影响&quot;">​</a></h3><p>即便放弃混合池，构建全 SSD 的 <code>size=3, min_size=2</code> pool，在 backfill 期间同样会遭遇性能问题：</p><ul><li><code>waiting_for_commit</code> 包含 <code>get_acting_recovery_backfill</code> 返回的所有 shard</li><li>backfill 目标 OSD 可能本身已处于高负载状态</li><li>primary OSD 必须等待该 OSD 的确认，导致写延迟飙升至 backfill 目标的水平</li></ul><h2 id="为何不能简单解耦-write-acknowledgment" tabindex="-1">为何不能简单解耦 Write Acknowledgment <a class="header-anchor" href="#为何不能简单解耦-write-acknowledgment" aria-label="Permalink to &quot;为何不能简单解耦 Write Acknowledgment&quot;">​</a></h2><p>演讲者指出，不能盲目解耦写确认机制，根本原因在于 <strong>CAP 定理中的一致性（Consistency）保证</strong>。当前架构确保了数据在集群中的强一致性，贸然解耦会引入数据安全风险。</p><h2 id="潜在解决方向-raft-协议中的-non-voting-learner" tabindex="-1">潜在解决方向：Raft 协议中的 Non-Voting Learner <a class="header-anchor" href="#潜在解决方向-raft-协议中的-non-voting-learner" aria-label="Permalink to &quot;潜在解决方向：Raft 协议中的 Non-Voting Learner&quot;">​</a></h2><p>演讲者提出了一个借鉴 <strong>Raft 共识算法</strong>的思路：</p><ul><li>Raft 协议引入了 <strong>non-voting learner</strong> 角色</li><li>这类节点接收数据复制，但不参与 quorum 投票</li><li>如果将 HDD OSD 设计为 non-voting learner，则： <ul><li>写确认不需要等待 HDD OSD 的响应</li><li>数据仍然会异步复制到 HDD，保证数据安全</li><li>写延迟由 SD OSD 决定，不受 HDD 拖累</li></ul></li></ul><p>演讲者认为，这是目前能想到的、既能实现混合池低成本目标、又能保持数据安全性的唯一可行架构方向。</p><h2 id="文档与源码的不一致问题" tabindex="-1">文档与源码的不一致问题 <a class="header-anchor" href="#文档与源码的不一致问题" aria-label="Permalink to &quot;文档与源码的不一致问题&quot;">​</a></h2><p>演讲者特别指出，当前 Ceph 文档中关于 <code>min_size</code> 的描述是针对 Reef 或 Quincy 等旧版本编写的，<strong>尚未更新以反映 Squid 中写确认机制的实际行为</strong>。源码与文档之间存在明显出入，这给运维人员和架构师带来了误导。</p><h2 id="总结与后续行动" tabindex="-1">总结与后续行动 <a class="header-anchor" href="#总结与后续行动" aria-label="Permalink to &quot;总结与后续行动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>议题</th><th>结论</th></tr></thead><tbody><tr><td>混合池在 Squid 下的性能</td><td>因 <code>waiting_for_apply</code> 被移除，性能不可接受</td></tr><tr><td>全 SSD 池 backfill 期间的写延迟</td><td>同样受 <code>waiting_for_commit</code> 机制影响</td></tr><tr><td>根本原因</td><td>write acknowledgment 等待 acting set 全部 OSD，不受 <code>min_size</code> 约束</td></tr><tr><td>潜在解决方案</td><td>引入类 Raft non-voting learner 机制，将 HDD OSD 排除在 quorum 之外</td></tr><tr><td>文档问题</td><td>需更新 <code>min_size</code> 相关文档以反映 Squid 实际行为</td></tr></tbody></table><p>演讲者希望社区能够将 non-voting learner 方向作为一个正式支持的 feature 进行探讨，从而在未来版本中合法、安全地实现混合池的低 TCO 目标。</p>',32)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
